/**
 * AUTO-GENERATED BY silc — DO NOT EDIT
 * Bun host for WebGPU game programs (ADR-012): static dist/, UDS HELLO/READY,
 * HTTP edge for settings/saves/telemetry/runs; Go owns durable SQLite tables.
 */
import { connect, type Socket } from "node:net";
import { join } from "node:path";
import { Database } from "bun:sqlite";

const socketPath = process.env.SILC_SOCKET || "";
const port = Number(process.env.SILC_HTTP_PORT || "18140");
const dbPath = process.env.SILC_DB_PATH || join(import.meta.dir, "..", "data", "app.db");
const protocolVersion = 1;
const abiVersion = 1;
const dist = join(import.meta.dir, "dist");

function encodeFrame(value: unknown): Buffer {
  const payload = Buffer.from(JSON.stringify(value));
  const frame = Buffer.allocUnsafe(6 + payload.length);
  frame.writeUInt32LE(payload.length, 0);
  frame.writeUInt16LE(protocolVersion, 4);
  payload.copy(frame, 6);
  return frame;
}

function decodeFrame(buffer: Buffer): { frame: any; rest: Buffer } | null {
  if (buffer.length < 6) return null;
  const length = buffer.readUInt32LE(0);
  const version = buffer.readUInt16LE(4);
  if (version !== protocolVersion) throw new Error(`unsupported Silc protocol ${version}`);
  if (buffer.length < 6 + length) return null;
  const frame = JSON.parse(buffer.subarray(6, 6 + length).toString());
  return { frame, rest: buffer.subarray(6 + length) };
}

let supervisor: Socket | null = null;
let pending = Buffer.alloc(0);

function connectSupervisor(): Promise<void> {
  if (!socketPath) return Promise.resolve();
  return new Promise((resolve, reject) => {
    supervisor = connect(socketPath);
    supervisor.on("connect", () => {
      supervisor!.write(
        encodeFrame({
          type: "HELLO",
          worker_id: "bun",
          role: "bun",
          abi_version: abiVersion,
          pid: process.pid,
        }),
      );
      supervisor!.write(encodeFrame({ type: "READY", worker_id: "bun" }));
      resolve();
    });
    supervisor.on("data", (chunk) => {
      pending = Buffer.concat([pending, chunk]);
      while (true) {
        const decoded = decodeFrame(pending);
        if (!decoded) break;
        pending = decoded.rest;
      }
    });
    supervisor.on("error", reject);
    supervisor.on("close", () => {
      supervisor = null;
    });
  });
}

/** Ensure Go-owned game tables exist on the shared SQLite file (idempotent). */
function openDb(): Database {
  const db = new Database(dbPath, { create: true });
  db.exec(`
    CREATE TABLE IF NOT EXISTS game_settings (
      id TEXT PRIMARY KEY,
      data TEXT NOT NULL,
      updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
    CREATE TABLE IF NOT EXISTS game_saves (
      slot TEXT PRIMARY KEY,
      mode_id TEXT,
      pawn_json TEXT NOT NULL DEFAULT '{}',
      attributes_json TEXT NOT NULL DEFAULT '[]',
      score REAL NOT NULL DEFAULT 0,
      revision INTEGER NOT NULL DEFAULT 0,
      data TEXT NOT NULL DEFAULT '{}',
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
    CREATE TABLE IF NOT EXISTS game_runs (
      id TEXT PRIMARY KEY,
      mode_id TEXT NOT NULL,
      seed INTEGER NOT NULL,
      outcome TEXT,
      duration_ms INTEGER,
      started_at TEXT NOT NULL DEFAULT (datetime('now')),
      ended_at TEXT
    );
    CREATE TABLE IF NOT EXISTS game_events (
      id TEXT PRIMARY KEY,
      run_id TEXT,
      kind TEXT NOT NULL,
      payload TEXT NOT NULL,
      ts TEXT NOT NULL DEFAULT (datetime('now'))
    );
    CREATE TABLE IF NOT EXISTS game_telemetry (
      id TEXT PRIMARY KEY,
      kind TEXT NOT NULL,
      payload TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
  `);
  return db;
}

function contentType(path: string): string {
  if (path.endsWith(".html")) return "text/html; charset=utf-8";
  if (path.endsWith(".js") || path.endsWith(".mjs")) return "application/javascript; charset=utf-8";
  if (path.endsWith(".css")) return "text/css; charset=utf-8";
  if (path.endsWith(".json")) return "application/json; charset=utf-8";
  if (path.endsWith(".wasm")) return "application/wasm";
  if (path.endsWith(".png")) return "image/png";
  if (path.endsWith(".jpg") || path.endsWith(".jpeg")) return "image/jpeg";
  if (path.endsWith(".map")) return "application/json; charset=utf-8";
  return "application/octet-stream";
}

function isStaticAsset(pathname: string): boolean {
  return /\.(js|mjs|css|json|wasm|png|jpe?g|map|svg|woff2?|ttf|ico)$/i.test(pathname);
}

const cognitionPort = Number(process.env.SILC_COGNITION_PORT || "18141");
const cognitionUrl = process.env.SILC_COGNITION_URL || `http://127.0.0.1:${cognitionPort}`;

const ALLOWED_TACTICS = new Set([
  "suppress",
  "flank_left",
  "flank_right",
  "push",
  "retreat",
  "hold",
]);

function fallbackDirective(persona: string, context: any) {
  const hp = Number(context?.self?.hp ?? 100);
  const tactic =
    hp < 35 ? "retreat" : /flank/i.test(persona) ? "flank_left" : /breach/i.test(persona) ? "push" : "suppress";
  return {
    aggression: hp < 35 ? 0.3 : 0.7,
    preferred_tactic: tactic,
    bark: hp < 35 ? "Falling back!" : "Contact!",
    ttl_s: 4,
    revision: Date.now(),
    source: "bun-fallback",
  };
}

function normalizeDirective(raw: any, persona: string, context: any) {
  const base = fallbackDirective(persona, context);
  const tactic = ALLOWED_TACTICS.has(raw?.preferred_tactic) ? raw.preferred_tactic : base.preferred_tactic;
  return {
    aggression: Math.max(0, Math.min(1, Number(raw?.aggression ?? base.aggression))),
    preferred_tactic: tactic,
    bark: typeof raw?.bark === "string" ? raw.bark.slice(0, 80) : base.bark,
    ttl_s: Math.max(1, Math.min(12, Number(raw?.ttl_s ?? 4))),
    revision: Number(raw?.revision ?? Date.now()),
    source: raw?.source || "silclm",
  };
}

async function requestCognition(persona: string, context: unknown) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 1200);
  try {
    const res = await fetch(`${cognitionUrl}/think`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ persona, context }),
      signal: controller.signal,
    });
    if (!res.ok) return fallbackDirective(persona, context);
    const body = (await res.json()) as { ok?: boolean; directive?: any };
    if (!body.ok || !body.directive) return fallbackDirective(persona, context);
    return normalizeDirective(body.directive, persona, context);
  } catch {
    return fallbackDirective(persona, context);
  } finally {
    clearTimeout(timer);
  }
}

async function main() {
  await connectSupervisor();
  const db = openDb();

  Bun.serve({
    port,
    async fetch(req) {
      const url = new URL(req.url);
      let pathname = decodeURIComponent(url.pathname);

      if (pathname === "/api/health") {
        return Response.json({
          ok: true,
          role: "bun",
          supervisor: Boolean(supervisor),
          engines: ["bun", "cpython-bake", "go", "cpython-cognition"],
          cognition: cognitionUrl,
        });
      }

      if (pathname === "/api/settings" && req.method === "GET") {
        const row = db.query("SELECT data FROM game_settings WHERE id = ?").get("default") as
          | { data: string }
          | null;
        return Response.json(row ? JSON.parse(row.data) : {});
      }
      if (pathname === "/api/settings" && req.method === "PUT") {
        const body = await req.json();
        db.query(
          `INSERT INTO game_settings (id, data, updated_at)
           VALUES (?, ?, datetime('now'))
           ON CONFLICT(id) DO UPDATE SET data = excluded.data, updated_at = datetime('now')`,
        ).run("default", JSON.stringify(body ?? {}));
        return Response.json({ ok: true });
      }

      if (pathname === "/api/saves" && req.method === "GET") {
        const rows = db
          .query(
            `SELECT slot, mode_id, pawn_json, attributes_json, score, revision, data, created_at, updated_at
             FROM game_saves ORDER BY updated_at DESC`,
          )
          .all() as Array<{
          slot: string;
          mode_id: string | null;
          pawn_json: string;
          attributes_json: string;
          score: number;
          revision: number;
          data: string;
          created_at: string;
          updated_at: string;
        }>;
        return Response.json(
          rows.map((r) => ({
            id: r.slot,
            data: {
              slot: r.slot,
              modeId: r.mode_id,
              pawn: JSON.parse(r.pawn_json || "{}"),
              attributes: JSON.parse(r.attributes_json || "[]"),
              score: r.score,
              revision: r.revision,
              ...(JSON.parse(r.data || "{}") as object),
            },
            created_at: r.created_at,
            updated_at: r.updated_at,
          })),
        );
      }
      if (pathname === "/api/saves" && req.method === "POST") {
        const body = (await req.json()) as {
          id?: string;
          data?: {
            slot?: string;
            modeId?: string;
            pawn?: unknown;
            attributes?: unknown;
            score?: number;
            revision?: number;
          };
        };
        const slot = body.id || body.data?.slot || crypto.randomUUID();
        const data = body.data ?? {};
        const revision = Number(data.revision ?? Date.now());
        db.query(
          `INSERT INTO game_saves (slot, mode_id, pawn_json, attributes_json, score, revision, data, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))
           ON CONFLICT(slot) DO UPDATE SET
             mode_id = excluded.mode_id,
             pawn_json = excluded.pawn_json,
             attributes_json = excluded.attributes_json,
             score = excluded.score,
             revision = excluded.revision,
             data = excluded.data,
             updated_at = datetime('now')
           WHERE excluded.revision >= game_saves.revision`,
        ).run(
          slot,
          data.modeId ?? null,
          JSON.stringify(data.pawn ?? {}),
          JSON.stringify(data.attributes ?? []),
          Number(data.score ?? 0),
          revision,
          JSON.stringify(data),
        );
        return Response.json({ ok: true, id: slot });
      }

      if (pathname === "/api/runs/start" && req.method === "POST") {
        const body = (await req.json()) as { modeId?: string };
        const runId = crypto.randomUUID();
        const seed = (crypto.getRandomValues(new Uint32Array(1))[0] >>> 0) || 1;
        db.query(
          `INSERT INTO game_runs (id, mode_id, seed, started_at) VALUES (?, ?, ?, datetime('now'))`,
        ).run(runId, body.modeId || "default", seed);
        return Response.json({ runId, seed });
      }
      if (pathname === "/api/runs/end" && req.method === "POST") {
        const body = (await req.json()) as { runId?: string; outcome?: string };
        if (body.runId) {
          db.query(
            `UPDATE game_runs SET outcome = ?, ended_at = datetime('now'),
              duration_ms = CAST((julianday(datetime('now')) - julianday(started_at)) * 86400000 AS INTEGER)
             WHERE id = ?`,
          ).run(body.outcome || "quit", body.runId);
        }
        return Response.json({ ok: true });
      }

      if (pathname === "/api/telemetry" && req.method === "POST") {
        const body = (await req.json()) as { kind?: string; payload?: unknown; runId?: string };
        const id = crypto.randomUUID();
        const payload = JSON.stringify(body.payload ?? {});
        db.query(
          `INSERT INTO game_telemetry (id, kind, payload, created_at)
           VALUES (?, ?, ?, datetime('now'))`,
        ).run(id, body.kind || "event", payload);
        db.query(
          `INSERT INTO game_events (id, run_id, kind, payload, ts)
           VALUES (?, ?, ?, ?, datetime('now'))`,
        ).run(id, body.runId ?? null, body.kind || "event", payload);
        return Response.json({ ok: true, id });
      }

      if (pathname === "/api/cognition" && req.method === "POST") {
        const body = (await req.json()) as { persona?: string; context?: unknown };
        const started = Date.now();
        const directive = await requestCognition(body.persona || "Hostile", body.context ?? {});
        const id = crypto.randomUUID();
        const payload = JSON.stringify({
          persona: body.persona,
          context: body.context,
          directive,
          ms: Date.now() - started,
        });
        db.query(
          `INSERT INTO game_events (id, run_id, kind, payload, ts)
           VALUES (?, ?, ?, ?, datetime('now'))`,
        ).run(id, null, "cognition", payload);
        db.query(
          `INSERT INTO game_telemetry (id, kind, payload, created_at)
           VALUES (?, ?, ?, datetime('now'))`,
        ).run(id, "cognition", payload);
        return Response.json({ ok: true, directive });
      }

      if (pathname === "/" || pathname === "") pathname = "/index.html";
      const filePath = join(dist, pathname);
      const file = Bun.file(filePath);
      if (await file.exists()) {
        return new Response(file, {
          headers: {
            "content-type": contentType(pathname),
            "cache-control": "no-cache",
          },
        });
      }
      if (isStaticAsset(pathname) || pathname.startsWith("/assets/") || pathname.startsWith("/baked/")) {
        return new Response(`Not found: ${pathname}`, {
          status: 404,
          headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-cache" },
        });
      }
      const index = Bun.file(join(dist, "index.html"));
      if (await index.exists()) {
        return new Response(index, {
          headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" },
        });
      }
      return new Response("Silc game host: dist/ missing — run silc build", { status: 503 });
    },
  });

  console.log(`silc game host http://127.0.0.1:${port}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
